def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    max_affordable_threat = 0.0

    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
            rich_opp += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            affordable = min(float(bid), float(opp.get('budget', 0) + opp.get('daily_salary', 0)))
            if affordable > max_affordable_threat:
                max_affordable_threat = affordable

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, max_affordable_threat + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.82, max_affordable_threat + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.72, avg_prev + 1.0)
    else:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.62, avg_prev + 1.0)
        elif loose_supply:
            bid = DAILY_SALARY * 0.34
        else:
            bid = DAILY_SALARY * 0.48

    if urgent_opp >= 2:
        bid += 6.0
    elif urgent_opp == 1:
        bid += 3.0

    if rich_opp >= 2 and tight_supply:
        bid += 4.0

    if highest_prev >= 140:
        bid = min(bid, DAILY_SALARY * 0.78 if hp > 4 and no_water_days == 0 else bid)
    elif highest_prev >= 100 and hp > 5 and no_water_days == 0 and not tight_supply:
        bid = min(bid, DAILY_SALARY * 0.55)

    if day >= 8:
        bid += 5.0
    if day == 10:
        bid += 8.0

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no one alive, spend conservatively
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Estimate how many units we can plausibly secure: fewer units => higher competition => higher bid
    # supply is in [15,25]; competition increases as supply approaches 15.
    tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)  # 0..1

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Determine target bid based on yesterday's max pressure
    base = DAILY_SALARY * (0.45 + 0.25 * tightness)  # mid-range, increases when supply tight

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If someone previously overbid aggressively, avoid mirroring; instead bid slightly above base.
        # If yesterday pressure was low, bid closer to base to save budget.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # Cindy-like behavior: don't chase; stay controlled.
            base = DAILY_SALARY * (0.50 + 0.20 * tightness)
        elif highest_prev_bid <= DAILY_SALARY * 0.35:
            base = DAILY_SALARY * (0.40 + 0.15 * tightness)
        else:
            base = max(base, highest_prev_bid * 0.55)

    # Urgency adjustment: if low HP or already in no-water streak, bid higher to avoid death
    if my_hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * (0.80 + 0.15 * tightness)
    elif my_hp <= 4.0:
        base = max(base, DAILY_SALARY * (0.65 + 0.10 * tightness))

    # Budget cap
    bid = float(min(my_budget, base))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_day = day_context['day']

    days_left = EPISODE_DAYS - current_day + 1

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.05)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    if my_hp <= 2 or my_no_water_days >= 1 or (days_left <= 2 and my_hp < 5):
        emergency_bid = DAILY_SALARY * 1.0 

        if highest_prev_bid > DAILY_SALARY * 0.9:
            emergency_bid = max(emergency_bid, highest_prev_bid + 5)

        return min(my_budget, emergency_bid)

    HIGH_COMPETITION_THRESHOLD = DAILY_SALARY * 0.85
    MODERATE_COMPETITION_THRESHOLD = DAILY_SALARY * 0.50

    if highest_prev_bid >= HIGH_COMPETITION_THRESHOLD:
        if my_hp > 5:
            bid = min(my_budget, max(DAILY_SALARY * 0.75, highest_prev_bid + 2))
            return min(bid, DAILY_SALARY * 1.05)
        else:
            return min(my_budget, max(DAILY_SALARY * 0.9, highest_prev_bid + 5))
    elif highest_prev_bid >= MODERATE_COMPETITION_THRESHOLD:
        if my_hp > 5:
            return min(my_budget, max(DAILY_SALARY * 0.6, highest_prev_bid + 1))
        else:
            return min(my_budget, max(DAILY_SALARY * 0.75, highest_prev_bid + 5))
    else:
        return min(my_budget, DAILY_SALARY * 0.6)

    return min(my_budget, DAILY_SALARY * 0.7)
